// Function to get a certain field from app_fd_d_preinscription table
public String getFieldFromPreinscription(String npi, String fieldName) {
 String result = null;
 Connection con = null;
 PreparedStatement ps = null;
 ResultSet rs = null;
 
 try {
 con = AppUtil.getApplicationContext().getBean("setupDataSource", javax.sql.DataSource.class).getConnection();
 String sql = "SELECT l.c_email FROM app_fd_d_preinscription p join app_fd_user_login l on (l.c_email=p.createdby) WHERE c_npi =?";
 ps = con.prepareStatement(sql);
 ps.setString(1, npi);
 rs = ps.executeQuery();
 
 if (rs.next()) {
 result = rs.getString(1);
 }
 } catch (SQLException e) {
 LogUtil.error("getFieldFromPreinscription", e, "Error executing SQL query");
 } finally {
 try {
 if (rs != null) rs.close();
 if (ps != null) ps.close();
 if (con != null) con.close();
 } catch (SQLException e) {
 LogUtil.error("getFieldFromPreinscription", e, "Error closing SQL resources");
 }
 }
 
 return result;
}


public void transferUserToDepartment(String userID, String newDepartmentId) {
 DirectoryManager directoryManager = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");
 
 // Get the user by user ID
 User user = directoryManager.getUserById(userId);
 if (user == null) {
 System.out.println("User not found");
 return;
 }
 EmploymentDao employmentDao =(EmploymentDao) AppUtil.getApplicationContext().getBean("employmentDao");
 // UuidGenerator uuid = UuidGenerator.getInstance();
 // String pId = uuid.getUuid();
 // Employment emp = new Employment();
 // emp.setId(pId);
 // emp.setUserId(userID);
 // emp.setOrganizationId("rsu");
 // emp.setDepartmentId(newDepartmentId);
 employmentDao.unassignUserFromDepartment(userID, "demandeur_enLigne");
 // employmentDao.addEmployment(emp);
 employmentDao.assignUserToDepartment(userID, newDepartmentId);

}

// Example usage
String npi = "#variable.npi#";
String fieldName = "p.createdby";
String fieldValue = getFieldFromPreinscription(npi, fieldName);
LogUtil.info("fieldValue: " , fieldValue);
String userId = fieldValue;
String newDepartmentId = "personneRadie";
transferUserToDepartment(userId, newDepartmentId);"}}]}

