 rs.close();
 selectPstmt.close();
 

 // Update query for the demandes in app_fd_d_preinscription based on selected NPIs
 String updateQuery = "UPDATE app_fd_d_preinscription SET c_statut_demande = ? , c_id_enquete = ? , c_identmen = ? WHERE c_npi = ?";
