public void HitApi(String lien) {
 HttpURLConnection connHTTP = null;
 BufferedReader reader = null;
 StringBuilder responseContent = new StringBuilder();

 try {
 URL url = new URL(lien);
 connHTTP = (HttpURLConnection) url.openConnection();
 connHTTP.setRequestMethod("GET");
 connHTTP.setRequestProperty("Accept", "application/json");

 int status = connHTTP.getResponseCode();
 LogUtil.info("response code", String.valueOf(status));

 InputStream inputStream = (status >= 300) ? connHTTP.getErrorStream() : connHTTP.getInputStream();
 reader = new BufferedReader(new InputStreamReader(inputStream,StandardCharsets.UTF_8));

 String line;
 while ((line = reader.readLine()) != null) {
 responseContent.append(line);
 if (status >= 300) {
 LogUtil.info("response error", line);
 } else {
 LogUtil.info("response success", line);
 JSONObject jsonResponse = new JSONObject(line);
 String Score = String.valueOf(jsonResponse.getDouble("Score "));
 String category=jsonResponse.getString("Category ");
 AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
 String recordid = appService.getOriginProcessId(workflowAssignment.getProcessId());
 // String recordid = "f5b19dfa-614d-4e5a-b65b-922407049ca6";
 String query2 = "update app_fd_pmt set c_score=?,c_categorie=? where id=?;";
 UpdateScore(query2,Score,category,recordid);
 }
 }

 } catch (Exception e) {
 LogUtil.error("RSU", e, "Error consuming API calcul de score");
 } finally {
 try {
 if (reader != null) reader.close();
 } catch (IOException e) {
 LogUtil.error("RSU", e, "Error closing reader");
 }
 if (connHTTP != null) connHTTP.disconnect();
 }
}

public String getIdMen(String query, String recordid) {
 String id_men = "";

 try{
 Connection con = ((DataSource) AppUtil.getApplicationContext().getBean("setupDataSource")).getConnection();
 PreparedStatement stmt = con.prepareStatement(query);
 stmt.setString(1, recordid);
 ResultSet rs = stmt.executeQuery();
 while(rs.next()) {
 id_men = rs.getString(1);
 }
 con.close();
 
 } catch (SQLException e) {
 LogUtil.error("RSU", e, "Error executing SQL query");
 con.close();
 } catch (Exception ex) {
 LogUtil.error("RSU", ex, "Error in get ident men function enquette calc score");
 con.close();
 }
 
 return id_men;
}

public void UpdateScore(String query, String score,String category,String recordid){
 try{
 Connection con = ((DataSource) AppUtil.getApplicationContext().getBean("setupDataSource")).getConnection();
 PreparedStatement stmt = con.prepareStatement(query);
 stmt.setString(1, score);
 stmt.setString(2, category);
 stmt.setString(3, recordid);
 stmt.executeUpdate();
 con.close();
 
 } catch (SQLException e) {
 LogUtil.error("RSU", e, "Error executing SQL query");
 con.close();
 } catch (Exception ex) {
 LogUtil.error("RSU", ex, "Error in updateScore function process enquette ");
 }
}
