String selectMembers = "select concat(c_nom,' ',c_prenom) as name,c_fonction,c_presence,c_structure from app_fd_membre_commission where c_id_commission=? ;";
stmt = con.prepareStatement(selectMembers);
stmt.setString(1, recordid);
rs = stmt.executeQuery();
JSONArray MembreArray = new JSONArray();
while (rs.next()) {
 JSONObject member = new JSONObject();
 member.put("name", rs.getString("name"));
 member.put("structure", rs.getString("c_structure"));
 member.put("fonction", rs.getString("c_fonction"));
 member.put("presence", rs.getString("c_presence"));
 MembreArray.put(member); 
 }
 data.put("membre", MembreArray);
 String selectDossier = "select c_id_dossier from app_fd_dossier_comm_org where c_id_commission=? ;";
 stmtDossier = con.prepareStatement(selectDossier);
 stmtDossier.setString(1, recordid);
 rs = stmtDossier.executeQuery();
 while (rs.next()) {
 String idDossier= rs.getString("c_id_dossier");
 ids.put(idDossier);
 PreparedStatement stmt2 = con.prepareStatement("select c_id_demande as IDDemande ,datecreated as dateDemande,c_decision,c_motif from app_fd_acces_donnees where id=?");
 stmt2.setString(1, idDossier);
 rs = stmt2.executeQuery();
 while (rs.next()) {
 JSONObject decision = new JSONObject();
 data.put("IDDemande",rs.getString("IDDemande"));
 data.put("IDDemande2",rs.getString("IDDemande"));
 data.put("dateDemande",rs.getString("dateDemande"));
 if(("c_decision)").equals("Accorder l'accès")){
 data.put("x","X");
 }else if(("c_decision)").equals("Accorder un accès partiel")){
 data.put("y","X");
 data.put("y1",rs.getString("c_motif"));
 }else{
 data.put("n","X");
 data.put("n1",rs.getString("c_motif"));
 } 
 }
 PreparedStatement stmt3 = con.prepareStatement("select c_nom_prg as institution , CONCAT (c_responsable, ' ', c_fonction) as responsable from app_fd_insc_programme where c_contact_electronique_prg=(select createdby from app_fd_acces_donnees where id=?);");
 stmt3.setString(1,idDossier);
 rs2 = stmt3.executeQuery();
 while (rs2.next()) {
