 data.put("institution",rs2.getString("institution"));
 data.put("responsable",rs2.getString("responsable"));
 }
 LogUtil.info("------------data------------->", data.toString());
 jsonData.put("data", data);
 jsonData.put("output_path", output_path+"/acces_donnees/"+idDossier);
 jsonData.put("output_file_name", output_file_name);
 LogUtil.info("---------------------------->6", jsonData.toString());
 String UpdateFile = "update app_fd_acces_donnees set c_rapport=? where id=? ;";
 stmtUpdateFileName = con.prepareStatement(UpdateFile);
 stmtUpdateFileName.setString(1, output_file_name2);
 stmtUpdateFileName.setString(2, idDossier);
 stmtUpdateFileName.executeUpdate();
 HitApi(lien,jsonData);
 }
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
wm.activityVariable(workflowAssignment.getActivityId(),"dossierArray", ids.toString());
 rs.close();
 stmt.close();
 con.close();
} catch (SQLException e) {
 LogUtil.error("RSU", e, "Error executing SQL query");
} catch (Exception ex) {
 LogUtil.error("RSU", ex, "Error in script generation pv commission");
}
