 try {
 // Define SOAP endpoint and request properties
 String endpoint = "https://10.208.0.78";
 String soapAction = "CITIZEN_BY_NPI_ANPS";

 // Construct SOAP XML request
 String soapRequestXML = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
 + "<soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\" "
 + "xmlns:xro=\"http://x-road.eu/xsd/xroad.xsd\" "
 + "xmlns:iden=\"http://x-road.eu/xsd/identifiers\" "
 + "xmlns:ns=\"http://x-road.eu/xsd/connector/CITIZEN_BY_NPI_ANPS/v1\">"
 + "<soapenv:Header>"
 + "<xro:client iden:objectType=\"SUBSYSTEM\">"
 + "<iden:xRoadInstance>BJ</iden:xRoadInstance>"
 + "<iden:memberClass>GOV</iden:memberClass>"
 + "<iden:memberCode>ANPS</iden:memberCode>"
 + "<iden:subsystemCode>RSU</iden:subsystemCode>"
 + "</xro:client>"
 + "<xro:service iden:objectType=\"SERVICE\">"
 + "<iden:xRoadInstance>BJ</iden:xRoadInstance>"
 + "<iden:memberClass>GOV</iden:memberClass>"
 + "<iden:memberCode>ANIP</iden:memberCode>"
 + "<iden:subsystemCode>RNP</iden:subsystemCode>"
 + "<iden:serviceCode>CITIZEN_BY_NPI_ANPS</iden:serviceCode>"
 + "<iden:serviceVersion>v1</iden:serviceVersion>"
 + "</xro:service>"
 + "<xro:userId></xro:userId>"
 + "<xro:id></xro:id>"
 + "<xro:protocolVersion>4.0</xro:protocolVersion>"
 + "</soapenv:Header>"
 + "<soapenv:Body>"
 + "<ns:CITIZEN_BY_NPI_ANPS>"
 + "<NPI>#variable.npi#</NPI>"
 + "</ns:CITIZEN_BY_NPI_ANPS>"
 + "</soapenv:Body>"
 + "</soapenv:Envelope>";

 // Open HTTP connection
 URL url = new URL(endpoint);
 HttpURLConnection conn = (HttpURLConnection) url.openConnection();
 conn.setRequestMethod("POST");
 conn.setDoOutput(true);
 conn.setRequestProperty("Content-Type", "text/xml;charset=UTF-8");
 conn.setRequestProperty("SOAPAction", soapAction);

 // Send the SOAP request
 OutputStream os = conn.getOutputStream();
 os.write(soapRequestXML.getBytes("UTF-8"));
 os.flush();
 os.close();

 // Get the SOAP response
 InputStream is = conn.getInputStream();
 BufferedReader br = new BufferedReader(new InputStreamReader(is));
 StringBuilder response = new StringBuilder();
 String line;
 while ((line = br.readLine()) != null) {
 response.append(line);
 }
 br.close();
 is.close();
 String xmlResponse = response.toString();

 if (xmlResponse.isEmpty()) {
 LogUtil.info("SOAP Response", "Response is empty");
 } else {
 LogUtil.info("SOAP Response", xmlResponse);

 // Parse XML response
 DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
 factory.setNamespaceAware(true);
 DocumentBuilder builder = factory.newDocumentBuilder();
 Document doc = builder.parse(new java.io.ByteArrayInputStream(xmlResponse.getBytes("UTF-8")));
 XPathFactory xPathFactory = XPathFactory.newInstance();
 XPath xpath = xPathFactory.newXPath();

 // Extract relevant fields
 String npi = xpath.evaluate("//*[local-name()='CITIZEN_BY_NPI_ANPSResponse']/*[local-name()='NPI']", doc);
 String formNumber = xpath.evaluate("//*[local-name()='CITIZEN_BY_NPI_ANPSResponse']/*[local-name()='FORM_NUMBER']", doc);
 String lastName = xpath.evaluate("//*[local-name()='CITIZEN_BY_NPI_ANPSResponse']/*[local-name()='LASTNAME']", doc);
 String firstName = xpath.evaluate("//*[local-name()='CITIZEN_BY_NPI_ANPSResponse']/*[local-name()='FIRSTNAME']", doc);
 String birthDate = xpath.evaluate("//*[local-name()='CITIZEN_BY_NPI_ANPSResponse']/*[local-name()='BIRTHDATE']", doc);
 String phoneNumber = xpath.evaluate("//*[local-name()='CITIZEN_BY_NPI_ANPSResponse']/*[local-name()='PHONE_NUMBER']", doc);
 String birthPlace = xpath.evaluate("//*[local-name()='CITIZEN_BY_NPI_ANPSResponse']/*[local-name()='BIRTH_PLACE']", doc);

 LogUtil.info("NPI", npi);
 LogUtil.info("Form Number", formNumber);
 LogUtil.info("Last Name", lastName);
 LogUtil.info("First Name", firstName);
 LogUtil.info("Birth Date", birthDate);
 LogUtil.info("Phone Number", phoneNumber);
 
 DateTimeFormatter inputFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss");

 // Parse the input date
 LocalDateTime dateTime = LocalDateTime.parse(birthDate, inputFormatter);
 
 // Define output format
 DateTimeFormatter outputFormatter = DateTimeFormatter.ofPattern("MM/dd/yyyy");
 
 // Format and print the date
 String formattedDate = dateTime.format(outputFormatter);
 
 
 WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(),"name", lastName);
 wm.activityVariable(workflowAssignment.getActivityId(),"prenom", firstName);
 wm.activityVariable(workflowAssignment.getActivityId(),"place", birthPlace);
 wm.activityVariable(workflowAssignment.getActivityId(),"birthday", formattedDate);
 }

 // Log the response
 LogUtil.info("SOAP Response", response.toString());

 } catch (Exception e) {
 LogUtil.error("SOAP Post Processing Tool", e, "Error occurred while making SOAP request");
 }"}}]}

