public void HitApi(String lien,JSONObject jsonData){
try {
 URL url = new URL(lien);
 connHTTP = (HttpURLConnection) url.openConnection();
 
 LogUtil.info("---------------------------->7", "");
 
 
 // Request setup
 connHTTP.setRequestMethod("POST");
 connHTTP.setRequestProperty("Content-Type", "application/json;charset=UTF-8");
 connHTTP.setRequestProperty("Accept", "application/json");
 connHTTP.setDoOutput(true);
 
 
 OutputStream os = connHTTP.getOutputStream();
 byte[] input = jsonData.toString().getBytes("utf-8");
 os.write(input, 0, input.length);
 
 
 // The response from the server
 int status = connHTTP.getResponseCode();

 // LogUtil.info("-----> json data ", jsonData.toString());

 
 LogUtil.info("response code ", String.valueOf(status));
 
 
 if (status >= 300) {
 reader = new BufferedReader(new InputStreamReader(connHTTP.getErrorStream()));
 while ((line = reader.readLine()) != null) {
 responseContent.append(line);
 }
 reader.close();
 } else {
 reader = new BufferedReader(new InputStreamReader(connHTTP.getInputStream()));
 while ((line = reader.readLine()) != null) {
 responseContent.append(line);
 }
 reader.close();
 }
} catch (Exception e) {
 LogUtil.error("RSU", e, "Error in hitApi method");
} finally {
 connHTTP.disconnect();
}
}
String source_path = "#envVariable.pathSourceCommissionDonnes#";
String output_path = "#envVariable.gen_path#";
String output_file_name = "";
String output_file_name2 = "";

JSONObject jsonData = new JSONObject();
JSONArray ids = new JSONArray();
jsonData.put("source_path", source_path);
JSONObject data = new JSONObject();


try {
 Connection con = null;
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 String commission_president = "#variable.president#";
 DateTimeFormatter dtf = DateTimeFormatter.ofPattern("yyyy-MM-dd hh:mm a");
 DateTimeFormatter newDateFormat = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 LocalDateTime dateTime = LocalDateTime.parse("#variable.date_com#", dtf);
 // LocalDateTime dateTime = LocalDateTime.parse("2025-04-10 12:00 AM", dtf);
 String monthDay = dateTime.format(newDateFormat);
 data.put("nom_pres_seance", commission_president);
 data.put("day_month", monthDay);
 data.put("salle","#variable.adresse#");
 output_file_name = "RSU_PVcommission.docx";
 output_file_name2 = "RSU_PVcommission.pdf";
LogUtil.info("--------------QUERY membre-------------->", "");
String selectMembers = "select concat(c_nom,' ',c_prenom) as name,c_fonction,c_presence,c_structure from app_fd_membre_commission where c_id_commission=? ;";
stmt = con.prepareStatement(selectMembers);
stmt.setString(1, recordid);
rs = stmt.executeQuery();
JSONArray MembreArray = new JSONArray();
while (rs.next()) {
 JSONObject member = new JSONObject();
 member.put("name", rs.getString("name"));
 member.put("fonction", rs.getString("c_fonction"));
 member.put("presence", rs.getString("c_presence"));
 member.put("structure", rs.getString("c_structure"));
 MembreArray.put(member); 
 }
 data.put("membre", MembreArray);
 String selectDossier = "select c_id_dossier from app_fd_dossier_comm_org where c_id_commission=? ;";
 stmtDossier = con.prepareStatement(selectDossier);
 stmtDossier.setString(1, recordid);
 rs = stmtDossier.executeQuery();
 int numberDossier = 0;
 while (rs.next()) {
 numberDossier++;
 String idDossier= rs.getString("c_id_dossier");
 JSONArray dataArray = new JSONArray();
 
 ids.put(idDossier);
 PreparedStatement stmt2 = con.prepareStatement("select d.c_id_demande as IDDemande ,d.datecreated as dateDemande,d.c_decision,d.c_motif ,p.c_nom_prg as org from app_fd_acces_donnees d join app_fd_insc_programme p on (p.c_contact_electronique_prg=d.createdby) where d.id=?");
 stmt2.setString(1, idDossier);
 rs = stmt2.executeQuery();

 while (rs.next()) {
 JSONObject decision = new JSONObject();
 decision.put("IDDemande",rs.getString("IDDemande"));
 decision.put("dateDemande",rs.getString("dateDemande"));
 decision.put("cat",rs.getString("c_decision")); 
 decision.put("c_motif",rs.getString("c_motif")); 
 decision.put("num",numberDossier); 
 decision.put("org",rs.getString("org"));
 dataArray.put(decision);
 }
 data.put("listDemande",dataArray);
 
 }
 LogUtil.info("------------data------------->", data.toString());
 jsonData.put("data", data);
 jsonData.put("output_path", output_path+"/commission_donnes/"+recordid);
 jsonData.put("output_file_name", output_file_name);
 LogUtil.info("---------------------------->6", jsonData.toString());
 String UpdateFile = "update app_fd_commission_donnes set c_pv_commission=? where id=? ;";
 stmtUpdateFileName = con.prepareStatement(UpdateFile);
 stmtUpdateFileName.setString(1, output_file_name2);
 stmtUpdateFileName.setString(2, recordid);
 stmtUpdateFileName.executeUpdate();
 HitApi(lien,jsonData);
 rs.close();
 stmt.close();
 con.close();
} catch (SQLException e) {
 LogUtil.error("RSU", e, "Error executing SQL query");
} catch (Exception ex) {
 LogUtil.error("RSU", ex, "Error in script generation pv commission");
}
