public boolean checkIfAlone(String npi){
 Connection con = null;
 PreparedStatement stmtSelectFolders = null;
 ResultSet rs1 = null;
 boolean isAlone = false;
 try {
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 stmtSelectFolders = con.prepareStatement("select count(*) from app_fd_table_individus where c_id_enquete=(select id from app_fd_pmt where c_npi_preinscription=?);");
 if (!con.isClosed()) {
 stmtSelectFolders.setString(1, npi);
 
 rs1 = stmtSelectFolders.executeQuery();
 while (rs1.next()) {
 if(rs1.getInt(1) == 1){
 LogUtil.info("count of enquete for npi "+npi+" is ",rs1.getInt(1).toString());
 isAlone = true;
 }
 }
 }
 } catch (Exception e) {
 LogUtil.error("verifying NPI and enquete for reclassement ", e, "error");
 } finally {
 if (rs1 != null) {
 try {
 rs1.close();
 } catch (SQLException e) {
 LogUtil.error("Error closing ResultSet", e, "error");
 }
 }
 if (stmtSelectFolders != null) {
 try {
 stmtSelectFolders.close();
 } catch (SQLException e) {
 LogUtil.error("Error closing PreparedStatement", e, "error");
 }
 }
 if (con != null) {
 try {
 con.close();
 } catch (SQLException e) {
 LogUtil.error("Error closing Connection", e, "error");
 }
 }
 }
 return isAlone;
}



