{"script":"import java.util.ArrayList;
import java.util.Collection;
import org.joget.apps.app.service.AppUtil;
import org.joget.directory.model.User;
import org.joget.directory.model.service.ExtDirectoryManager;
import org.joget.workflow.model.WorkflowActivity;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.commons.util.LogUtil;
import java.lang.String;
public Collection getAssignees(WorkflowActivity activity) {
 Connection con =null;
 String compagne_enquete="#form.pmt.compagne_enquete#";
 LogUtil.info("---compagne_enquete id ------",compagne_enquete);
 Collection assignees = new ArrayList();
 ExtDirectoryManager directoryManager = (ExtDirectoryManager) pluginManager.getBean("directoryManager");
 //Get users using directory manager
 try{
 Connection con=null;
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 String query=" SELECT c_chef_equipe from app_fd_planif_enquete where c_compagne_enquete=?";
 PreparedStatement pstmt = con.prepareStatement(query);
 pstmt.setString(1,compagne_enquete);
 ResultSet rs= pstmt.executeQuery();
 String id="";
 if(rs.next()){
 String id= rs.getString("c_chef_equipe");
 LogUtil.info("chef id-----",id);
 assignees.add(id);
 }else{
 LogUtil.info("chef inesxistant -----",rs.getString("c_chef_equipe"));
 }
 
 
 
 }catch (SQLException e) {
 LogUtil.error("Beanshell", e, "SQL Exception occurred during insert.");
 } finally {
 // Close the resources
 try {
 if (con != null) con.close();
 } catch (SQLException e) {
 LogUtil.error("Beanshell", e, "Error closing resources.");
 }
 }
 return assignees;
}
//call getAssignees method with injected variable
return getAssignees(workflowActivity);"}

